/*
 * Form 8949 bindings. First generated by `form-engine generate-bindings`
 * (2026-05-18), then rewritten by hand (MANUAL EDIT, 2026-10-15) around
 * the copy plan (copyPlan.ts).
 *
 * The engine keeps Form 8949 as ONE form. Every row, box, and total
 * reads the CURRENT copy: `info.form8949Copies[info.form8949CopyIndex]`.
 * The engine evaluates copy 0; the renderer (render/renderCopies.ts)
 * re-evaluates the form per copy and merges the pages. Schedule D reads
 * the per-box totals from FilingInfo, not these per-copy totals.
 *
 * Rows, boxes, and totals are built in loops over the catalog's fixed
 * layout: two parts × 11 rows.
 */

import {
  defineForm,
  roundDollars,
  sum,
  type BindingFn,
  type FormAccessor,
} from "../../defineForm.js";
import type { Form8949Box } from "../../facts/index.js";
import { ROWS_PER_PAGE, type Form8949Copy, type Form8949Page } from "./copyPlan.js";
import type { Form8949FilingInfo } from "./filingInfo.js";
import type { Form8949 } from "./types.js";

type Fn = (f: FormAccessor<Form8949>, info: Form8949FilingInfo) => unknown;
type Bindings = Partial<{ [K in keyof Form8949]: BindingFn<Form8949, Form8949FilingInfo, K> }>;
type Notes = Partial<{ [K in keyof Form8949]: string }>;

/* The two parts of the form: page prefix, part key, and which copy page fills it. */
const PARTS = [
  { prefix: "0.part1", page: (c: Form8949Copy) => c.partI },
  { prefix: "1.part2", page: (c: Form8949Copy) => c.partII },
] as const;

/* Catalog checkbox per box. */
const BOX_FIELDS: Record<Form8949Box, keyof Form8949> = {
  "partI.boxA": "0.part1.box_a_short_term_basis_reported",
  "partI.boxB": "0.part1.box_b_short_term_basis_not_reported",
  "partI.boxC": "0.part1.box_c_short_term_not_on_1099b",
  "partI.boxG": "0.part1.box_g_short_term_1099da_basis_reported",
  "partI.boxH": "0.part1.box_h_short_term_1099da_basis_not_reported",
  "partI.boxI": "0.part1.box_i_short_term_digital_not_on_1099da",
  "partII.boxD": "1.part2.box_d_long_term_basis_reported",
  "partII.boxE": "1.part2.box_e_long_term_basis_not_reported",
  "partII.boxF": "1.part2.box_f_long_term_not_on_1099b",
  "partII.boxJ": "1.part2.box_j_long_term_1099da_basis_reported",
  "partII.boxK": "1.part2.box_k_long_term_1099da_basis_not_reported",
  "partII.boxL": "1.part2.box_l_long_term_digital_not_on_1099da",
};

function currentCopy(info: Form8949FilingInfo): Form8949Copy | undefined {
  return info.form8949Copies?.[info.form8949CopyIndex ?? 0];
}

/*
 * Column (a), "100 sh. XYZ Co." style. Brokers often print the quantity
 * in box 1a already ("91.207 sh SAMPLE INC", "0.242151 EXAMPLECOIN");
 * a description that starts with a number is kept as is.
 */
function describe(quantity: number, description: string): string {
  return /^\d/.test(description) ? description : `${quantity} sh ${description}`;
}

/*
 * Per-row gain/loss, the IRS column (h) formula: (d) proceeds − (e)
 * basis + (g) adjustment. Empty rows (no proceeds) return undefined so
 * unused widgets do not render "0".
 */
function rowGainLoss(
  proceeds: unknown,
  costBasis: unknown,
  adjustment: unknown,
): number | undefined {
  if (typeof proceeds !== "number") return undefined;
  return (
    proceeds -
    (typeof costBasis === "number" ? costBasis : 0) +
    (typeof adjustment === "number" ? adjustment : 0)
  );
}

/* Header name and SSN on both pages. */
function headerBindings(): Record<string, Fn> {
  const name: Fn = (_, info) =>
    info.taxpayerFirstName && info.taxpayerLastName
      ? `${info.taxpayerFirstName} ${info.taxpayerLastName}`
      : undefined;
  const ssn: Fn = (_, info) => info.taxpayerSSN;
  return {
    "0.header.taxpayer_name": name,
    "1.header.taxpayer_name": name,
    "0.header.ssn": ssn,
    "1.header.ssn": ssn,
  };
}

/* One checkbox per box: checked when the current copy's page uses that box. */
function boxBindings(): Record<string, Fn> {
  const out: Record<string, Fn> = {};
  for (const [box, fieldId] of Object.entries(BOX_FIELDS)) {
    const pick = box.startsWith("partI.") ? PARTS[0].page : PARTS[1].page;
    out[fieldId] = (_, info) => {
      const copy = currentCopy(info);
      return copy && pick(copy)?.box === box ? true : undefined;
    };
  }
  return out;
}

/* Rows 1–11 of one part: columns (a)–(e) from the copy page, (h) computed. */
function rowBindings(prefix: string, page: (c: Form8949Copy) => Form8949Page | undefined) {
  const out: Record<string, Fn> = {};
  for (let n = 1; n <= ROWS_PER_PAGE; n++) {
    const row = (info: Form8949FilingInfo) => {
      const copy = currentCopy(info);
      return copy ? page(copy)?.rows[n - 1] : undefined;
    };
    const key = `${prefix}.row${n}`;
    out[`${key}_description`] = (_, info) => {
      const r = row(info);
      return r ? describe(r.trade.quantity, r.trade.description) : undefined;
    };
    out[`${key}_date_acquired`] = (_, info) => row(info)?.trade.dateAcquired;
    out[`${key}_date_sold`] = (_, info) => row(info)?.trade.dateSold;
    /* Whole dollars (IRS: if you round, round all amounts); (h) = rounded (d) − (e). */
    out[`${key}_proceeds`] = (_, info) => roundDollars(row(info)?.trade.proceeds);
    out[`${key}_cost_basis`] = (_, info) => roundDollars(row(info)?.basis);
    out[`${key}_gain_loss`] = (f) =>
      rowGainLoss(f[`${key}_proceeds`], f[`${key}_cost_basis`], f[`${key}_adjustment_amount`]);
  }
  return out;
}

/*
 * Column totals for one part (this copy only): (d), (e), (h). Totals add
 * the sales with cents and round once (IRS rule, as Schedule D does);
 * (h) = rounded (d) − rounded (e).
 */
function totalBindings(prefix: string, page: (c: Form8949Copy) => Form8949Page | undefined) {
  const rows = (info: Form8949FilingInfo) => {
    const copy = currentCopy(info);
    return copy ? page(copy)?.rows : undefined;
  };
  const total =
    (amount: (r: Form8949Page["rows"][number]) => number | undefined): Fn =>
    (_, info) => {
      const rs = rows(info);
      return rs && rs.length > 0 ? roundDollars(sum(...rs.map(amount))) : undefined;
    };
  return {
    [`${prefix}.totals_proceeds`]: total((r) => r.trade.proceeds),
    [`${prefix}.totals_cost_basis`]: total((r) => r.basis),
    [`${prefix}.totals_gain_loss`]: ((f) => {
      const d = f[`${prefix}.totals_proceeds`];
      return typeof d === "number" ? d - sum(f[`${prefix}.totals_cost_basis`]) : undefined;
    }) as Fn,
  };
}

function adjustmentNotes(): Record<string, string> {
  const out: Record<string, string> = {};
  for (const { prefix } of PARTS) {
    for (let n = 1; n <= ROWS_PER_PAGE; n++) {
      out[`${prefix}.row${n}_adjustment_code`] =
        "Adjustment codes (wash sale etc.) are not modeled yet.";
      out[`${prefix}.row${n}_adjustment_amount`] =
        "Adjustment amounts (column g) are not modeled yet.";
    }
    out[`${prefix}.totals_adjustment_amount`] =
      "Adjustment amounts (column g) are not modeled yet.";
  }
  return out;
}

/*
 * register() wraps the defineForm side effect. Callers import it and
 * run the registration once at startup. The call is idempotent; a
 * second call overwrites in place.
 */
export function register(): void {
  const bindings: Record<string, Fn> = {
    ...headerBindings(),
    ...boxBindings(),
    ...PARTS.reduce((acc, p) => ({ ...acc, ...rowBindings(p.prefix, p.page) }), {}),
    ...PARTS.reduce((acc, p) => ({ ...acc, ...totalBindings(p.prefix, p.page) }), {}),
  };
  defineForm<Form8949, Form8949FilingInfo>("form-8949", {
    // Must-file comes from decisions.scope.must_file_8949 (resolve8949Info).
    mustFile: (info) => info.mustFile8949,
    mustFileDecisionKey: "decisions.scope.must_file_8949",
    bindings: bindings as Bindings,
    unsupported: adjustmentNotes() as Notes,
  });
}
